--=====================================================================
--                  RETAIL SALES ANALYTICS PROJECT
--=====================================================================


=====================================================================
--SECTION 1: EXECUTIVE KPI ANALYSIS
=====================================================================

--Objective:
--Provide management with an overview of the company's overall
--business performance.

--Business Questions:


--1. What is the total sales revenue generated by the company?

SELECT
    ROUND(SUM(sales),2) AS total_revenue
FROM superstore;



--2. What is the total profit earned by the company?

SELECT
    ROUND(SUM(profit),2) AS total_profit
FROM superstore;



--3. How many unique orders have been placed?

SELECT
    COUNT(DISTINCT order_id) AS total_orders
FROM superstore;



--4. How many unique customers have made purchases?

SELECT
    COUNT(DISTINCT customer_id) AS unique_customers
FROM superstore;



--5. What is the total quantity of products sold?

SELECT
    SUM(quantity) AS sold_product_quantity
FROM superstore;



--6. What is the average order value (AOV)?

SELECT
    ROUND(
        SUM(sales) / NULLIF(COUNT(DISTINCT order_id),0),
        2
    ) AS average_order_value
FROM superstore;



--7. What is the average profit generated per order?

SELECT
    ROUND(
        SUM(profit) / NULLIF(COUNT(DISTINCT order_id),0),
        2
    ) AS average_profit_per_order
FROM superstore;



--8. What is the overall profit margin (%)?

SELECT
    ROUND(
        (SUM(profit) / NULLIF(SUM(sales),0)) * 100,
        2
    ) AS profit_margin_percentage
FROM superstore;



--9. What is the average discount offered to customers?

SELECT
    ROUND(AVG(discount) * 100,2) AS average_discount_percentage
FROM superstore;




=====================================================================
--SECTION 2: SALES PERFORMANCE ANALYSIS
=====================================================================

--Objective:
--Evaluate overall sales performance over time.


--10. How have monthly sales changed over time?

SELECT
    YEAR(order_date) AS sales_year,
    MONTH(order_date) AS sales_month,
    DATENAME(MONTH,order_date) AS month_name,
    ROUND(SUM(sales),2) AS total_sales
FROM superstore
GROUP BY
    YEAR(order_date),
    MONTH(order_date),
    DATENAME(MONTH,order_date)
ORDER BY
    sales_year,
    sales_month;



--11. How has monthly profit changed over time?

SELECT
    YEAR(order_date) AS profit_year,
    MONTH(order_date) AS profit_month,
    DATENAME(MONTH,order_date) AS month_name,
    ROUND(SUM(profit),2) AS total_profit
FROM superstore
GROUP BY
    YEAR(order_date),
    MONTH(order_date),
    DATENAME(MONTH,order_date)
ORDER BY
    profit_year,
    profit_month;



--12. Which year generated the highest sales?

SELECT TOP 1
    YEAR(order_date) AS sales_year,
    ROUND(SUM(sales),2) AS total_sales
FROM superstore
GROUP BY
    YEAR(order_date)
ORDER BY
    total_sales DESC;



--13. Which year generated the highest profit?

SELECT TOP 1
    YEAR(order_date) AS profit_year,
    ROUND(SUM(profit),2) AS total_profit
FROM superstore
GROUP BY
    YEAR(order_date)
ORDER BY
    total_profit DESC;



--14. Which month recorded the highest sales?

SELECT TOP 1
    MONTH(order_date) AS sales_month,
    DATENAME(MONTH,order_date) AS month_name,
    ROUND(SUM(sales),2) AS total_sales
FROM superstore
GROUP BY
    MONTH(order_date),
    DATENAME(MONTH,order_date)
ORDER BY
    total_sales DESC;



--15. Which month recorded the lowest sales?

SELECT TOP 1
    MONTH(order_date) AS sales_month,
    DATENAME(MONTH,order_date) AS month_name,
    ROUND(SUM(sales),2) AS total_sales
FROM superstore
GROUP BY
    MONTH(order_date),
    DATENAME(MONTH,order_date)
ORDER BY
    total_sales ASC;



--16. What is the Year-over-Year (YoY) sales growth?

WITH yearly_sales AS
(
    SELECT
        YEAR(order_date) AS sales_year,
        SUM(sales) AS total_sales
    FROM superstore
    GROUP BY
        YEAR(order_date)
)

SELECT
    sales_year,
    ROUND(total_sales,2) AS total_sales,

    ROUND(
        LAG(total_sales) OVER(ORDER BY sales_year),
        2
    ) AS previous_year_sales,

    ROUND(
        (
        (total_sales -
        LAG(total_sales) OVER(ORDER BY sales_year))
        /
        NULLIF(LAG(total_sales) OVER(ORDER BY sales_year),0)
        ) * 100,
        2
    ) AS yoy_sales_growth_percentage

FROM yearly_sales
ORDER BY
    sales_year;



--17. What is the Year-over-Year (YoY) profit growth?

WITH yearly_profit AS
(
    SELECT
        YEAR(order_date) AS profit_year,
        SUM(profit) AS total_profit
    FROM superstore
    GROUP BY
        YEAR(order_date)
)

SELECT
    profit_year,
    ROUND(total_profit,2) AS total_profit,

    ROUND(
        LAG(total_profit) OVER(ORDER BY profit_year),
        2
    ) AS previous_year_profit,

    ROUND(
        (
        (total_profit -
        LAG(total_profit) OVER(ORDER BY profit_year))
        /
        NULLIF(LAG(total_profit) OVER(ORDER BY profit_year),0)
        ) * 100,
        2
    ) AS yoy_profit_growth_percentage

FROM yearly_profit
ORDER BY
    profit_year;






    =====================================================================
--SECTION 3: CUSTOMER ANALYSIS
=====================================================================

--Objective:
--Identify high-value customers and understand customer behaviour.


--18. Who are the top 10 customers by sales?

SELECT TOP 10
    customer_id,
    customer_name,
    ROUND(SUM(sales),2) AS total_sales
FROM superstore
GROUP BY
    customer_id,
    customer_name
ORDER BY
    total_sales DESC;



--19. Who are the top 10 customers by profit?

SELECT TOP 10
    customer_id,
    customer_name,
    ROUND(SUM(profit),2) AS total_profit
FROM superstore
GROUP BY
    customer_id,
    customer_name
ORDER BY
    total_profit DESC;



--20. Which customer segment generates the highest revenue?

SELECT TOP 1
    segment,
    ROUND(SUM(sales),2) AS total_revenue
FROM superstore
GROUP BY
    segment
ORDER BY
    total_revenue DESC;



--21. Which customer segment generates the highest profit?

SELECT TOP 1
    segment,
    ROUND(SUM(profit),2) AS total_profit
FROM superstore
GROUP BY
    segment
ORDER BY
    total_profit DESC;



--22. What is the average spending per customer?

SELECT
    customer_id,
    customer_name,
    ROUND(
        SUM(sales) / COUNT(DISTINCT order_id),
        2
    ) AS average_customer_spending
FROM superstore
GROUP BY
    customer_id,
    customer_name
ORDER BY
    average_customer_spending DESC;



--23. Which customers have generated losses?

SELECT
    customer_id,
    customer_name,
    ROUND(SUM(profit),2) AS total_loss
FROM superstore
GROUP BY
    customer_id,
    customer_name
HAVING
    SUM(profit) < 0
ORDER BY
    total_loss ASC;




