--SECTION 4: PRODUCT ANALYSIS
=====================================================================

--Objective:
--Evaluate product performance and profitability.


--24. Which are the top 10 best-selling products?

SELECT TOP 10
    product_id,
    product_name,
    ROUND(SUM(sales),2) AS total_sales
FROM superstore
GROUP BY
    product_id,
    product_name
ORDER BY
    total_sales DESC;



--25. Which are the top 10 most profitable products?

SELECT TOP 10
    product_id,
    product_name,
    ROUND(SUM(profit),2) AS total_profit
FROM superstore
GROUP BY
    product_id,
    product_name
ORDER BY
    total_profit DESC;



--26. Which products generate the highest losses?

SELECT
    product_name,
    ROUND(SUM(profit),2) AS total_loss
FROM superstore
GROUP BY
    product_name
HAVING
    SUM(profit) < 0
ORDER BY
    total_loss ASC;



--27. Which category generates the highest sales?

SELECT TOP 1
    category,
    ROUND(SUM(sales),2) AS total_sales
FROM superstore
GROUP BY
    category
ORDER BY
    total_sales DESC;



--28. Which category generates the highest profit?

SELECT TOP 1
    category,
    ROUND(SUM(profit),2) AS total_profit
FROM superstore
GROUP BY
    category
ORDER BY
    total_profit DESC;



--29. Which sub-category generates the highest sales?

SELECT TOP 1
    sub_category,
    ROUND(SUM(sales),2) AS total_sales
FROM superstore
GROUP BY
    sub_category
ORDER BY
    total_sales DESC;



--30. Which sub-category generates the highest profit?

SELECT TOP 1
    sub_category,
    ROUND(SUM(profit),2) AS total_profit
FROM superstore
GROUP BY
    sub_category
ORDER BY
    total_profit DESC;



--31. What are the top 3 products in each category?

WITH product_sales AS
(
    SELECT
        category,
        product_name,
        SUM(sales) AS total_sales
    FROM superstore
    GROUP BY
        category,
        product_name
),

ranked_products AS
(
    SELECT
        category,
        product_name,
        total_sales,
        ROW_NUMBER() OVER
        (
            PARTITION BY category
            ORDER BY total_sales DESC
        ) AS product_rank
    FROM product_sales
)

SELECT
    category,
    product_name,
    ROUND(total_sales,2) AS total_sales,
    product_rank
FROM ranked_products
WHERE product_rank <= 3
ORDER BY
    category,
    product_rank;




